from .money import MAX_CENTS, amount_cents, cents_to_decimal, format_amount


def make_invoice(amounts):
    items = list(amounts)  # copy; the caller's container is not modified
    total_cents = 0
    for item in items:
        total_cents += amount_cents(item)
        if total_cents > MAX_CENTS:
            raise ValueError("invoice total must be at most 1000000.00")
    return {"total": format_amount(cents_to_decimal(total_cents)), "count": len(items)}
